package dev.industrialtechnology.builder;

import cpw.mods.fml.common.*;
import cpw.mods.fml.common.event.*;
import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import cpw.mods.fml.common.gameevent.TickEvent;
import cpw.mods.fml.relauncher.Side;
import java.nio.file.*;
import java.nio.charset.StandardCharsets;
import java.util.*;
import net.minecraft.init.*;
import net.minecraft.item.*;
import net.minecraft.nbt.NBTTagCompound;
import net.minecraft.server.MinecraftServer;
import net.minecraft.entity.player.EntityPlayerMP;
import net.minecraft.world.*;
import net.minecraft.util.*;
import net.minecraftforge.common.*;
import net.minecraftforge.common.util.FakePlayer;
import net.minecraftforge.event.world.BlockEvent;

@Mod(modid="industrialtech_builder_checks",name="Building Stick checks",version="1",dependencies="required-after:industrialtech")
public final class BuilderNativeChecks {
    private final List<String> report=new ArrayList<String>();private int failed,phase,wait=25;private FakePlayer player;private WorldServer world;private ItemStack tool;private Cancel cancel;
    public static final class Cancel{boolean enabled;int count;@SubscribeEvent public void place(BlockEvent.PlaceEvent e){if(enabled){count++;e.setCanceled(true);}}}
    @Mod.EventHandler public void init(FMLInitializationEvent event){if(!Boolean.getBoolean("industrialtech.builderTest"))return;if(event.getSide()==Side.CLIENT)dev.industrialtechnology.builder.client.BuilderClientChecks.install();else FMLCommonHandler.instance().bus().register(this);}
    void check(boolean ok,String why){if(!ok)throw new AssertionError(why);}
    void test(String text,Runnable action){try{action.run();report.add("PASS: "+text);}catch(Throwable e){failed++;report.add("FAIL: "+text+" :: "+e);e.printStackTrace();}}
    private void use(int x,int y,int z,int side){player.setPosition(x+.5,y+2,z-2.5);check(player.theItemInWorldManager.activateBlockOrUseItem(player,world,tool,x,y,z,side,.5F,.5F,.5F),"Native use failed");}
    private void mode(BuildMode mode,boolean hollow){BuilderService.cancel(player,false);BuilderData.tag(tool).setByte("BuildMode",(byte)mode.ordinal());BuilderData.tag(tool).setBoolean("Hollow",hollow);BuilderData.clear(tool);}
    private void start(int x,int endX,int z){world.setBlock(x,64,z,Blocks.stone,0,2);world.setBlock(endX,64,z,Blocks.stone,0,2);use(x,64,z,1);use(endX,64,z,1);}
    private int stock(){int n=0;for(ItemStack s:player.inventory.mainInventory)if(s!=null&&s.getItem()==Item.getItemFromBlock(Blocks.stone))n+=s.stackSize;return n;}
    private int placed(int x,int endX,int z){int n=0;for(int i=x;i<=endX;i++)if(world.getBlock(i,65,z)==Blocks.stone)n++;return n;}
    private void finish(){report.add("Failed: "+failed);try{Files.write(Paths.get("builder-server.txt"),report,StandardCharsets.UTF_8);}catch(Exception e){throw new RuntimeException(e);}MinecraftServer.getServer().initiateShutdown();phase=99;}
    @SubscribeEvent public void tick(TickEvent.ServerTickEvent event){if(phase==99||event.phase!=TickEvent.Phase.END||--wait>0)return;try{
        if(phase==0){world=MinecraftServer.getServer().worldServerForDimension(0);for(int x=0;x<8;x++)for(int z=0;z<8;z++)world.getChunkFromChunkCoords(x,z);player=new FakePlayer(world,new com.mojang.authlib.GameProfile(UUID.fromString("954be44e-cea4-4b2c-a09f-62d191ad45f2"),"BuildChecks")){public void sendPlayerAbilities(){}public void addChatMessage(IChatComponent c){}};player.playerNetServerHandler=new net.minecraft.network.NetHandlerPlayServer(MinecraftServer.getServer(),new net.minecraft.network.NetworkManager(false),player){public void sendPacket(net.minecraft.network.Packet p){}};player.theItemInWorldManager.setGameType(WorldSettings.GameType.SURVIVAL);tool=new ItemStack(BuilderRegistry.stick);player.inventory.mainInventory[0]=tool;player.inventory.currentItem=0;
            test("The Building Stick has an ordinary Survival crafting recipe",()->{net.minecraft.inventory.InventoryCrafting grid=new net.minecraft.inventory.InventoryCrafting(new net.minecraft.inventory.Container(){public boolean canInteractWith(net.minecraft.entity.player.EntityPlayer p){return true;}},3,3);grid.setInventorySlotContents(1,new ItemStack(Items.iron_ingot));grid.setInventorySlotContents(4,new ItemStack(Items.redstone));grid.setInventorySlotContents(7,new ItemStack(Items.stick));ItemStack result=net.minecraft.item.crafting.CraftingManager.getInstance().findMatchingRecipe(grid,world);check(result!=null&&result.getItem()==BuilderRegistry.stick,"Crafting recipe missing or conflicting");});
            test("Material selection uses native right-click and survives NBT with namespaced material IDs",()->{world.setBlock(32,64,32,Blocks.stone,0,2);player.setSneaking(true);use(32,64,32,1);player.setSneaking(false);check(BuilderData.material(tool).getItem()==Item.getItemFromBlock(Blocks.stone),"Wrong picked material");check(BuilderData.mode(tool)==BuildMode.LINE,"Default line mode lost after creating NBT");NBTTagCompound n=new NBTTagCompound();tool.writeToNBT(n);check(BuilderData.material(ItemStack.loadItemStackFromNBT(n)).getItem()==Item.getItemFromBlock(Blocks.stone),"Material NBT failed");});
            player.inventory.mainInventory[1]=new ItemStack(Blocks.stone,10);mode(BuildMode.LINE,false);start(32,36,32);phase=1;wait=6;return;}
        if(phase==1){test("Real Survival placements consume exactly one inventory block per placed position",()->{check(!BuilderService.active(player)&&placed(32,36,32)==5&&stock()==5,"Conservation failed: "+placed(32,36,32)+" / "+stock());});cancel=new Cancel();cancel.enabled=true;MinecraftForge.EVENT_BUS.register(cancel);mode(BuildMode.LINE,false);start(32,36,36);phase=2;wait=6;return;}
        if(phase==2){test("Forge protection rolls back world edits and refunds reserved materials",()->{check(cancel.count>0&&placed(32,36,36)==0&&stock()==5,"Canceled placement consumed/created blocks");});MinecraftForge.EVENT_BUS.unregister(cancel);player.inventory.mainInventory[1]=new ItemStack(Blocks.stone,2);mode(BuildMode.LINE,false);start(32,36,40);phase=3;wait=6;return;}
        if(phase==3){test("Exhausted inventories stop safely without creating free blocks",()->{check(!BuilderService.active(player)&&placed(32,36,40)==2&&stock()==0,"Out-of-stock behavior");});player.theItemInWorldManager.setGameType(WorldSettings.GameType.CREATIVE);mode(BuildMode.LINE,false);start(32,36,44);phase=4;wait=6;return;}
        if(phase==4){test("Creative builds do not need or manufacture inventory stacks",()->{check(placed(32,36,44)==5&&stock()==0,"Creative inventory changed");});test("Machines/containers are excluded and clicking one never opens its GUI",()->{world.setBlock(40,64,44,Blocks.chest,0,2);player.setSneaking(true);Object container=player.openContainer;use(40,64,44,1);player.setSneaking(false);check(player.openContainer==container&&BuilderData.material(tool).getItem()==Item.getItemFromBlock(Blocks.stone),"Container picked or opened");});mode(BuildMode.BOX,false);world.setBlock(64,64,64,Blocks.stone,0,2);world.setBlock(96,96,96,Blocks.stone,0,2);use(64,64,64,1);use(96,96,96,1);phase=5;wait=12;return;}
        if(phase==5){test("Oversized shapes are rejected before any world block is placed",()->{check(!BuilderService.active(player)&&world.isAirBlock(64,65,64)&&world.isAirBlock(65,65,64),"Oversized shape partially placed");});mode(BuildMode.BOX,false);world.setBlock(48,64,48,Blocks.stone,0,2);world.setBlock(62,78,62,Blocks.stone,0,2);use(48,64,48,1);use(62,78,62,1);phase=6;wait=5;return;}
        if(phase==6){test("Server work respects fixed scan/placement limits and cancellation keeps already paid blocks",()->{check(BuilderService.lastScans<=BuilderService.GLOBAL_SCAN&&BuilderService.lastAttempts>0&&BuilderService.lastAttempts<=BuilderService.GLOBAL_ATTEMPTS,"Global budgets exceeded or placements were not exercised");BuilderService.cancel(player,false);check(!BuilderService.active(player),"Cancel failed");});test("Air endpoints reject coordinates beyond the player's reach",()->{mode(BuildMode.LINE,false);BuilderData.anchor(player,tool,new BuildPos(32,90,32),1);BuildCommand invalid=new BuildCommand(BuildCommand.AIR_END,0,BuildMode.LINE,false,new BuildPos(2000000,90,2000000));BuilderService.enqueue(player,invalid);BuilderService.step();check(!BuilderService.active(player)&&BuilderData.anchor(player,tool)!=null,"Remote endpoint accepted");});test("Special block items cannot redirect placement to a cell outside the requested shape",()->{mode(BuildMode.SINGLE,false);BuilderData.material(tool,new ItemStack(Blocks.stone_slab));world.setBlock(48,64,40,Blocks.stone,0,2);world.setBlock(48,66,40,Blocks.stone_slab,0,2);use(48,64,40,1);BuilderService.step();check(world.isAirBlock(48,65,40)&&world.getBlock(48,66,40)==Blocks.stone_slab,"Slab placement escaped its target cell");BuilderData.material(tool,new ItemStack(Blocks.stone));});test("Boundary placement never loads a neighboring chunk",()->{int cx=256,cz=256,x=cx*16+14,z=cz*16+7;world.getChunkFromChunkCoords(cx,cz);world.setBlock(x,64,z,Blocks.stone,0,2);world.setBlock(x+1,64,z,Blocks.stone,0,2);mode(BuildMode.LINE,false);use(x,64,z,1);use(x+1,64,z,1);world.theChunkProviderServer.unloadChunksIfNotNearSpawn(cx+1,cz);world.theChunkProviderServer.unloadQueuedChunks();check(!world.getChunkProvider().chunkExists(cx+1,cz),"Fixture neighbor stayed loaded");BuilderService.step();check(!world.getChunkProvider().chunkExists(cx+1,cz)&&world.isAirBlock(x,65,z)&&world.isAirBlock(x+1,65,z),"Boundary build forced a chunk or changed unsafe cells");});test("A changed held slot cannot change the Building Stick configuration",()->{BuildMode before=BuilderData.mode(tool);BuilderService.enqueue(player,new BuildCommand(BuildCommand.CONFIGURE,8,BuildMode.SPHERE,true,null));BuilderService.step();check(BuilderData.mode(tool)==before,"Stale slot packet accepted");});test("Logging out cancels active and queued actions",()->{mode(BuildMode.LINE,false);BuilderData.anchor(player,tool,new BuildPos(32,65,32),1);BuildMode before=BuilderData.mode(tool);new BuilderService().logout(new cpw.mods.fml.common.gameevent.PlayerEvent.PlayerLoggedOutEvent(player));BuilderService.enqueue(player,new BuildCommand(BuildCommand.CONFIGURE,0,BuildMode.SPHERE,true,null));BuilderService.step();check(!BuilderService.active(player)&&BuilderData.mode(tool)==before,"Logged-out command was accepted");});finish();}
    }catch(Throwable e){failed++;report.add("FAIL: fixture :: "+e);e.printStackTrace();finish();}}
}
